#include "gg_protocol.h"
#include <string.h>

uint16_t gg_crc16_ccitt(const uint8_t *data,size_t len){uint16_t crc=0xffff;size_t n;unsigned b;for(n=0;n<len;n++){crc^=(uint16_t)data[n]<<8;for(b=0;b<8;b++)crc=(crc&0x8000)?(uint16_t)((crc<<1)^0x1021):(uint16_t)(crc<<1);}return crc;}
size_t gg_cobs_encode(const uint8_t *in,size_t len,uint8_t *out,size_t cap){size_t read=0,write=1,code_at=0;uint8_t code=1;if(!out||cap<1)return 0;while(read<len){if(in[read]==0){if(code_at>=cap)return 0;out[code_at]=code;code=1;code_at=write++;if(write>cap)return 0;read++;}else{if(write>=cap)return 0;out[write++]=in[read++];code++;if(code==0xff){out[code_at]=code;code=1;code_at=write++;if(write>cap)return 0;}}}if(code_at>=cap)return 0;out[code_at]=code;return write;}
size_t gg_cobs_decode(const uint8_t *in,size_t len,uint8_t *out,size_t cap){size_t r=0,w=0;while(r<len){uint8_t code=in[r++];size_t count;if(code==0)return 0;count=(size_t)code-1;if(count>len-r||count>cap-w)return 0;if(count){memcpy(out+w,in+r,count);r+=count;w+=count;}if(code!=0xff&&r<len){if(w>=cap)return 0;out[w++]=0;}}return w;}
static void put16(uint8_t *p,uint16_t x){p[0]=(uint8_t)x;p[1]=(uint8_t)(x>>8);}
static uint16_t get16(const uint8_t *p){return (uint16_t)(p[0]|((uint16_t)p[1]<<8));}
size_t gg_frame_encode(uint8_t type,uint16_t seq,const uint8_t *payload,uint16_t plen,uint8_t *wire,size_t cap){uint8_t raw[GG_FRAME_MAX],encoded[GG_FRAME_MAX+4];size_t rawlen=GG_HEADER_SIZE+plen+2,n;if(rawlen>sizeof(raw)||cap<2)return 0;raw[0]=GG_PROTOCOL_VERSION;raw[1]=type;put16(raw+2,seq);put16(raw+4,plen);if(plen&&payload)memcpy(raw+6,payload,plen);put16(raw+6+plen,gg_crc16_ccitt(raw,6+plen));n=gg_cobs_encode(raw,rawlen,encoded,sizeof(encoded));if(!n||n+1>cap)return 0;memcpy(wire,encoded,n);wire[n]=0;return n+1;}
int gg_frame_decode(const uint8_t *wire,size_t length,gg_frame_header_t *h,uint8_t *payload,size_t cap){uint8_t raw[GG_FRAME_MAX];size_t n;if(length&&wire[length-1]==0)length--;n=gg_cobs_decode(wire,length,raw,sizeof(raw));if(n<8||raw[0]!=GG_PROTOCOL_VERSION)return -1;h->version=raw[0];h->msg_type=raw[1];h->seq=get16(raw+2);h->payload_len=get16(raw+4);if(n!=(size_t)h->payload_len+8||h->payload_len>cap)return -2;if(get16(raw+6+h->payload_len)!=gg_crc16_ccitt(raw,6+h->payload_len))return -3;if(h->payload_len)memcpy(payload,raw+6,h->payload_len);return 0;}
